class Solution:
    def largestDivisibleSubset(self, nums: list[int]) -> list[int]:
        if not nums:return []
        nums.sort();n=len(nums);dp=[1]*n;prev=[-1]*n
        best=0
        for i in range(n):
            for j in range(i):
                if nums[i]%nums[j]==0 and dp[j]+1>dp[i]:
                    dp[i]=dp[j]+1;prev[i]=j
            if dp[i]>dp[best]:best=i
        out=[]
        while best!=-1:out.append(nums[best]);best=prev[best]
        return out[::-1]

import java.util.*;
class Solution {
    public List<Integer> largestDivisibleSubset(int[] nums) {
        List<Integer> out=new ArrayList<>();if(nums.length==0)return out;Arrays.sort(nums);int n=nums.length;
        int[]dp=new int[n],prev=new int[n];Arrays.fill(dp,1);Arrays.fill(prev,-1);int best=0;
        for(int i=0;i<n;i++){for(int j=0;j<i;j++)if(nums[i]%nums[j]==0&&dp[j]+1>dp[i]){dp[i]=dp[j]+1;prev[i]=j;}if(dp[i]>dp[best])best=i;}
        while(best!=-1){out.add(nums[best]);best=prev[best];}Collections.reverse(out);return out;
    }
}

class Solution:
    def wiggleMaxLength(self, nums: list[int]) -> int:
        if not nums:return 0
        up=down=1
        for i in range(1,len(nums)):
            if nums[i]>nums[i-1]:up=down+1
            elif nums[i]<nums[i-1]:down=up+1
        return max(up,down)

class Solution {
    public int wiggleMaxLength(int[] nums) {
        if(nums.length==0)return 0;int up=1,down=1;
        for(int i=1;i<nums.length;i++){if(nums[i]>nums[i-1])up=down+1;else if(nums[i]<nums[i-1])down=up+1;}
        return Math.max(up,down);
    }
}

class Solution:
    def combinationSum4(self, nums: list[int], target: int) -> int:
        dp=[0]*(target+1);dp[0]=1
        for total in range(1,target+1):
            for x in nums:
                if x<=total:dp[total]+=dp[total-x]
        return dp[target]

class Solution {
    public int combinationSum4(int[] nums,int target) {
        int[]dp=new int[target+1];dp[0]=1;
        for(int t=1;t<=target;t++)for(int x:nums)if(x<=t)dp[t]+=dp[t-x];
        return dp[target];
    }
}

class Solution:
    def kthSmallest(self, matrix: list[list[int]], k: int) -> int:
        n=len(matrix);lo,hi=matrix[0][0],matrix[-1][-1]
        while lo<hi:
            mid=(lo+hi)//2;r=n-1;c=0;count=0
            while r>=0 and c<n:
                if matrix[r][c]<=mid:count+=r+1;c+=1
                else:r-=1
            if count<k:lo=mid+1
            else:hi=mid
        return lo

class Solution {
    public int kthSmallest(int[][] matrix,int k) {
        int n=matrix.length,lo=matrix[0][0],hi=matrix[n-1][n-1];
        while(lo<hi){int mid=lo+(hi-lo)/2,count=0,r=n-1,c=0;
            while(r>=0&&c<n){if(matrix[r][c]<=mid){count+=r+1;c++;}else r--;}
            if(count<k)lo=mid+1;else hi=mid;
        }return lo;
    }
}

