    public boolean remove(int val){Set<Integer>s=indices.get(val);if(s==null||s.isEmpty())return false;int i=s.iterator().next();s.remove(i);int lastIndex=values.size()-1,last=values.get(lastIndex);values.set(i,last);Set<Integer>lastSet=indices.get(last);lastSet.add(i);lastSet.remove(lastIndex);values.remove(lastIndex);if(s.isEmpty())indices.remove(val);return true;}
