from collections import Counter
class Solution:
    def canConstruct(self, ransomNote: str, magazine: str) -> bool:
        counts=Counter(magazine)
        for c in ransomNote:
            if counts[c]==0:return False
            counts[c]-=1
        return True

class Solution {
    public boolean canConstruct(String ransomNote,String magazine) {
        int[]counts=new int[26];for(char c:magazine.toCharArray())counts[c-'a']++;
        for(char c:ransomNote.toCharArray())if(--counts[c-'a']<0)return false;
        return true;
    }
}

class Solution:
    def lexicalOrder(self, n: int) -> list[int]:
        out=[];curr=1
        for _ in range(n):
            out.append(curr)
            if curr*10<=n:curr*=10
            else:
                while curr%10==9 or curr+1>n:curr//=10
                curr+=1
        return out

import java.util.*;
class Solution {
    public List<Integer> lexicalOrder(int n) {
        List<Integer> out=new ArrayList<>(n);int curr=1;
        for(int i=0;i<n;i++){out.add(curr);if(curr*10<=n)curr*=10;else{while(curr%10==9||curr+1>n)curr/=10;curr++;}}
        return out;
    }
}
